// Resolves a ball/brick collision: flips the velocity on the face that was hit
// and pushes the ball out of the brick. Returns true if the collision was
// resolved.
export function bounceOffBrick(ball, brick) {
  // compute penetration on each axis
  const overlapLeft = ball.x + ball.r - brick.x;        // how far ball's right edge is past brick's left edge
  const overlapRight = brick.x + brick.w - (ball.x - ball.r); // how far ball's left edge is past brick's right edge
  const overlapTop = ball.y + ball.r - brick.y;
  const overlapBottom = brick.y + brick.h - (ball.y - ball.r);

  const minX = Math.min(overlapLeft, overlapRight);
  const minY = Math.min(overlapTop, overlapBottom);

  if (minX < minY) {
    // side hit: flip vx
    if (overlapLeft < overlapRight) {
      ball.x = brick.x - ball.r;  // push to the left
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r; // push to the right
      ball.vx = Math.abs(ball.vx);
    }
  } else if (minY < minX) {
    // top/bottom hit: flip vy
    if (overlapTop < overlapBottom) {
      ball.y = brick.y - ball.r; // push above
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r; // push below
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // equal penetration: diagonal hit, flip both
    // push out on both axes
    ...
  }
}
```

