```js
// Walks the ball's path between its previous and current position in small
// steps and resolves the bounce the moment the path enters the brick
// (anti-tunnelling: a fast ball must not jump clean over a brick).
// Leaves the ball at the resolved (pushed-out) position on a hit; otherwise
// restores it to the current position. Returns true if a bounce happened.
function sweepBrick(ball, brick, px, py) {
  const dx = ball.x - px;
  const dy = ball.y - py;
  const dist = Math.hypot(dx, dy);
  const steps = Math.max(1, Math.ceil(dist / 2));
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    ball.x = px + dx * t;
    ball.y = py + dy * t;
    if (collides(ball, brick)) {
      bounceOffBrick(ball, brick);
      return true;
    }
  }
  return false;
}
```

