// A fixed brick to bounce test balls off: x 90..130, y 100..120.
const BRICK = { x: 90, y: 100, w: 40, h: 20 };

function newBall(x, y, vx, vy) {
  return { x, y, r: 7, vx, vy };
}

test('bounceOffBrick: top-face hit flips vy only and pushes the ball out', () => {
  const ball = newBall(110, 105, 300, 300); // falling onto the brick's top face
  bounceOffBrick(ball, BRICK);
  assert.equal(ball.vy, -300, 'vy should flip upward on a top-face hit');
  assert.equal(ball.vx, 300, 'vx must be left exactly as it was');
  assert.equal(ball.y, BRICK.y - ball.r, 'ball pushed out above the brick');
  assert.equal(collides(ball, BRICK), false, 'no residual overlap');
});

test('bounceOffBrick: bottom-face hit flips vy only and pushes the ball out', () => {
  const ball = newBall(110, 115, -300, -300); // rising into the brick's bottom face
  bounceOffBrick(ball, BRICK);
  assert.equal(ball.vy, 300, 'vy should flip downward on a bottom-face hit');
  assert.equal(ball.vx, -300, 'vx must be left exactly as it was');
  assert.equal(ball.y, BRICK.y + BRICK.h + ball.r, 'ball pushed out below the brick');
  assert.equal(collides(ball, BRICK), false, 'no residual overlap');
});

test('bounceOffBrick: left-face hit flips vx only and pushes the ball out', () => {
  const ball = newBall(95, 110, 300, 50); // entering the brick from its left side
  bounceOffBrick(ball, BRICK);
  assert.equal(ball.vx, -300, 'vx should flip leftward on a left-face hit');
  assert.equal(ball.vy, 50, 'vy must be left exactly as it was');
  assert.equal(ball.x, BRICK.x - ball.r, 'ball pushed out on the left');
  assert.equal(collides(ball, BRICK), false, 'no residual overlap');
});

test('bounceOffBrick: right-face hit flips vx only and pushes the ball out', () => {
  const ball = newBall(125, 110, -300, -50); // entering the brick from its right side
  bounceOffBrick(ball, BRICK);
  assert.equal(ball.vx, 300, 'vx should flip rightward on a right-face hit');
  assert.equal(ball.vy, -50, 'vy must be left exactly as it was');
  assert.equal(ball.x, BRICK.x + BRICK.w + ball.r, 'ball pushed out on the right');
  assert.equal(collides(ball, BRICK), false, 'no residual overlap');
});

test('bounceOffBrick: equal penetration (corner) flips both components', () => {
  const ball = newBall(90, 100, 300, 300); // equally into the left edge and top edge
  bounceOffBrick(ball, BRICK);
  assert.equal(ball.vx, -300, 'vx flips on a diagonal hit');
  assert.equal(ball.vy, -300, 'vy flips on a diagonal hit');
  assert.equal(ball.x, BRICK.x - ball.r, 'ball pushed out on the left');
  assert.equal(ball.y, BRICK.y - ball.r, 'ball pushed out on top');
  assert.equal(collides(ball, BRICK), false, 'no residual overlap');
});

test('brickHit: seam between two bricks bounces exactly once', () => {
  // Two bricks 8 px apart (the real grid gap), with the ball spanning the seam:
  // it overlaps the upper brick from below and the lower brick from above.
  const upper = { x: 90, y: 80, w: 40, h: 20, alive: true, points: 10 };
  const lower = { x: 90, y: 108, w: 40, h: 20, alive: true, points: 10 };
  const ball = newBall(110, 104, 300, -300);
  ball.px = 110;
  ball.py = 104;

  const destroyed = brickHit(ball, [upper, lower]);

  assert.equal(destroyed.length, 2, 'both overlapping bricks are destroyed');
  assert.equal(upper.alive, false);
  assert.equal(lower.alive, false);
  assert.equal(ball.vy, 300, 'vy flipped exactly once (a double flip would cancel out)');
  assert.equal(ball.vx, 300, 'vx untouched by a top/bottom bounce');
  assert.equal(collides(ball, upper), false, 'ball pushed out of the upper brick');
});

test('brickHit: fast ball is swept back, not tunnelled through the brick', () => {
  // ballSpeed(6) = 710 px/s; a 50 ms frame moves the ball 35.5 px, more than
  // the 34 px (BRICK_H + diameter) needed to cross a brick in one step.
  const state = createState(6);
  state.bricks = [{ x: 100, y: 100, w: 40, h: 20, alive: true, points: 10 }];
  state.ball = newBall(120, 128, 0, -710); // just below the brick, heading up

  step(state, 0.05);

  // After the step the ball is above the brick and overlaps nothing.
  assert.equal(state.ball.y, 92.5, 'sanity: the ball really jumped past the brick');
  assert.equal(collides(state.ball, state.bricks[0]), false);

  const destroyed = brickHit(state.ball, state.bricks);

  assert.equal(destroyed.length, 1, 'the swept brick is destroyed');
  assert.equal(state.bricks[0].alive, false);
  assert.ok(state.ball.vy > 0, 'ball bounces back down instead of plowing through');
  assert.ok(state.ball.y > state.bricks[0].y, 'ball pushed out below the brick');
});

