// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Brick collisions are resolved separately by
// `brickHit()` (called from `frame()`).
// Records the position before the move in `ball.px`/`ball.py` so the brick
// pass can sweep the path and catch bricks a fast ball would tunnel through.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;

