// re-overlap on the next frame (sticky bounce).
//
// - per face: the axis with the SMALLER penetration is the face that was hit;
//   flip that component (`vy` for top/bottom, `vx` for sides) and leave the
//   other component exactly as it was;
// - corner: equal penetration on both axes means a diagonal hit — flip both;
// - push out: reposition the ball just outside the brick rectangle.
export function bounceOffBrick(ball, brick) {
  // Penetration depth into each of the four edges.
  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);

  const minX = Math.min(left, right);
  const minY = Math.min(top, bottom);

  if (minX < minY) {
    // Side hit: flip vx only, push out on the hit side.
    if (left < right) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (minY < minX) {
    // Top/bottom hit: flip vy only, push out on the hit side.
    if (top < bottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // Corner: equal penetration on both axes — diagonal hit, flip both.
    if (left < right) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (top < bottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
}

// Walks the ball's path between its previous position (`px`, `py`) and its
// current one in small steps, and resolves the bounce the moment the path
// first enters the brick (anti-tunnelling: a fast ball must not jump clean
// over a brick between two frames). On a hit the ball is left at the resolved
// (pushed-out) position; otherwise it is left exactly where it was.
// Returns `true` if a bounce happened.
function sweepBrick(ball, brick, px, py) {
  const dx = ball.x - px;
  const dy = ball.y - py;
  const dist = Math.hypot(dx, dy);
  // Small enough steps to never hop over a brick (BRICK_H + ball diameter is
  // 34 px; the longest legal move is ~35.5 px at level 6 with a 50 ms frame).
  const steps = Math.max(1, Math.ceil(dist / 2));
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    ball.x = px + dx * t;
    ball.y = py + dy * t;
    if (collides(ball, brick)) {
      bounceOffBrick(ball, brick);
      return true;
    }
  }
  return false;
}

// Resolves all ball/brick collisions for one pass (see #1).
//
// - destroys every brick the ball overlaps, or swept through this frame;
// - the grid gap (8 px) is smaller than the ball (14 px across), so a seam
//   overlaps two bricks in the SAME pass: the bounce is applied exactly once
//   (`vy = -vy` twice would cancel out and the ball would plow through);
// - uses the previous position (`ball.px`/`ball.py`, recorded by `step()`)
//   to catch bricks a fast ball would otherwise tunnel through.
//
// Returns the destroyed bricks in hit order, so callers can score them.
export function brickHit(ball, bricks) {
  const destroyed = [];
  let bounced = false;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    // After the first bounce the ball has been repositioned: plain overlap
    // check for the remaining bricks (they are still destroyed, but only one
    // bounce per pass).
    const hit = bounced ? collides(ball, brick) : sweepBrick(ball, brick, px, py);
    if (hit) {
      brick.alive = false;
      destroyed.push(brick);
      bounced = true;
    }
  }
  return destroyed;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

